export function invoiceTotals(invoices) {
  if (!Array.isArray(invoices)) {
    throw new Error('Expected an array of invoices');
  }

  let count = 0;
  let totalCents = 0;
  for (const invoice of invoices) {
    if (invoice === null || typeof invoice !== 'object' ||
        (invoice.status !== 'paid' && invoice.status !== 'unpaid') ||
        !Number.isInteger(invoice.amountCents) || invoice.amountCents < 0) {
      throw new Error('Expected an invoice with paid/unpaid status and nonnegative integer amountCents');
    }
    if (invoice.status === 'paid') {
      count += 1;
      totalCents += invoice.amountCents;
    }
  }
  return { count, totalCents };
}

