import test from 'node:test';
import assert from 'node:assert/strict';
import { invoiceTotals } from './invoices.mjs';

function invoiceTest(name, scenario, caseId, category, run) {
  test(`${name} [${scenario}] [Test-type: Unit] [Case: ${caseId}] [Coverage: ${category}]`, run);
}

invoiceTest('mixed totals preserve caller data', 'INV-001', 'mixed-totals', 'positive', () => {
  const invoices = [
    { status: 'paid', amountCents: 1250, memo: ' Æ\n€ ', metadata: { tags: ['keep'] } },
    { status: 'unpaid', amountCents: 9999, metadata: { tags: ['unpaid'] } },
    { status: 'paid', amountCents: 75 },
  ];
  const before = structuredClone(invoices);
  const references = [...invoices];
  assert.deepEqual(invoiceTotals(invoices), { count: 2, totalCents: 1325 });
  assert.deepEqual(invoices, before);
  references.forEach((invoice, index) => assert.strictEqual(invoices[index], invoice));
});

invoiceTest('unpaid amounts do not contribute', 'INV-001', 'unpaid-excluded', 'negative', () => {
  const invoices = Object.freeze([
    Object.freeze({ status: 'unpaid', amountCents: 850 }),
    Object.freeze({ status: 'unpaid', amountCents: 0 }),
  ]);
  assert.deepEqual(invoiceTotals(invoices), { count: 0, totalCents: 0 });
  assert.deepEqual(invoices, [{ status: 'unpaid', amountCents: 850 }, { status: 'unpaid', amountCents: 0 }]);
});

invoiceTest('empty input returns fresh zeros', 'INV-001', 'empty', 'boundary', () => {
  const invoices = Object.freeze([]);
  const result = invoiceTotals(invoices);
  assert.deepEqual(result, { count: 0, totalCents: 0 });
  assert.notStrictEqual(result, invoiceTotals(invoices));
  assert.deepEqual(invoices, []);
});

invoiceTest('paid zero counts without changing frozen input', 'INV-001', 'paid-zero', 'boundary', () => {
  const invoices = Object.freeze([
    Object.freeze({ status: 'paid', amountCents: 0 }),
    Object.freeze({ status: 'unpaid', amountCents: 10 }),
  ]);
  assert.deepEqual(invoiceTotals(invoices), { count: 1, totalCents: 0 });
  assert.deepEqual(invoices, [{ status: 'paid', amountCents: 0 }, { status: 'unpaid', amountCents: 10 }]);
});

const nonArrays = [undefined, null, {}, 'invoices', 42, true, { 0: { status: 'paid', amountCents: 5 }, length: 1 }];
nonArrays.forEach((input, index) => {
  invoiceTest(`reject non-array ${index}`, 'INV-002', `non-array-${index}`, 'negative', () => {
    assert.throws(() => invoiceTotals(input), Error);
  });
});

const malformed = [null, undefined, 1, 'paid', {}, { status: 'pending', amountCents: 10 },
  { status: 'PAID', amountCents: 10 }, { amountCents: 10 }, { status: 'paid' }, { status: 'unpaid' }];
malformed.forEach((invoice, index) => {
  invoiceTest(`reject malformed entry ${index}`, 'INV-002', `malformed-${index}`, 'negative', () => {
    assert.throws(() => invoiceTotals([{ status: 'paid', amountCents: 5 }, invoice]), Error);
  });
});

const invalidAmounts = [
  ['negative', -1], ['fractional', 0.5], ['string', '100'], ['nan', NaN],
  ['infinite', Infinity], ['boolean', true], ['null', null], ['bigint', 1n],
];
for (const status of ['paid', 'unpaid']) {
  for (const [label, amountCents] of invalidAmounts) {
    invoiceTest(`reject ${status} ${label}`, 'INV-002', `${status}-${label}`, 'negative', () => {
      const invoices = [{ status: 'paid', amountCents: 20 }, { status, amountCents }];
      const before = structuredClone(invoices);
      assert.throws(() => invoiceTotals(invoices), Error);
      assert.deepEqual(invoices, before);
    });
  }
}

invoiceTest('zero is a valid invoice amount', 'INV-002', 'valid-zero', 'positive', () => {
  assert.deepEqual(invoiceTotals([{ status: 'paid', amountCents: 0 }, { status: 'unpaid', amountCents: 0 }]),
    { count: 1, totalCents: 0 });
});

invoiceTest('sparse arrays reject missing invoices', 'INV-002', 'sparse-array', 'boundary', () => {
  assert.throws(() => invoiceTotals(new Array(1)), Error);
});

